function twoSum(numbers: number[], target: number): number[] {
  let left = 0;
  let right = numbers.length - 1;

  while (left < right) {
    const sum = numbers[left] + numbers[right];

    if (sum === target) {
      // Индексация в ответе — с единицы
      return [left + 1, right + 1];
    }

    if (sum < target) {
      // Сумма мала — нужно число побольше, двигаем левый указатель вправо
      left++;
    } else {
      // Сумма велика — нужно число поменьше, двигаем правый указатель влево
      right--;
    }
  }

  // По условию решение всегда существует
  return [];
}

// Время: O(n) — указатели вместе проходят массив один раз
// Память: O(1)
